from pathlib import Path
import csv,json
W=Path(__file__).resolve().parent
s=json.loads((W/'accepted-summary.json').read_text(encoding='utf8'));assert s['root_accepted_complete']==40
rows=list(csv.DictReader((W/'accepted-results.csv').open(encoding='utf8')))
out=['# Forty further multi-sector dip candidates','', 'All forty original priority ranks 111–150 completed bounded scientific review and root acceptance, with no substitutions.','',', '.join(f'{v} {k.lower()}' for k,v in s['verdicts'].items())+'.','', '| ID | TIC | Physical result | Catalogue status | Adopted period (d) |','|---|---|---|---|---|']
for r in rows:out.append(f"| [{r['sample_id']}]({Path(r['report']).relative_to(W).as_posix()}) | {r['tic']} | {r['physical_verdict']} | {r['novelty_status']} | {r['period_days'] or 'unresolved'} |")
out+=['','Physical evidence and catalogue novelty remain separate. SCOPED_NONMATCH means no prior target EB identification in the enumerated successful checks; it is not exhaustive priority clearance. Known recoveries do not add new systems. Source ambiguities, partial events, integer aliases and invalid observations remain explicit in each report. Refuted describes the selected target signal, not the impossibility of binarity.','', 'This follows the unchanged original priority ordering after the accepted hundred and next ten. All 150 selected reviews leave 2,654 of the original 2,804 priority leads outside these campaigns. Original queues remain unchanged. The ranking was informed by earlier outcomes; these descriptive results cannot estimate population occurrence or validate the ranking.','', 'Shared receipts cover successful Gaia/SIMBAD queries, local primary tables and 160 VizieR target cones. The known-source VSX positive control succeeded; later Kostov-specific controls timed out, as retained in the catalogue report. Alternative TESSCut reductions of cached observations use the same photons, not new observing occasions. Source packets initially verified 396 cached FITS files.','', 'The linked evidence and final manifests preserve the local raw-data hashes. FITS are local caches and are not all archived in Git. No shared paper, claim ledger or public repository was changed during review. Integration assessment is separate in `integration/`; it does not itself promote discovery claims or allocate review IDs.','']
(W/'REPORT.md').write_text('\n'.join(out),encoding='utf8')
